import type { Region, StructureInfo, Tissue } from './types';

export const HIP_PELVIS_PATH = '/msk-anatomy-atlas/lower-extremity/hip-pelvis';
export type HipSide = 'whole' | 'right' | 'left';
export const HIP_SIDES: { id: HipSide; label: string }[] = [
  { id: 'whole', label: 'Whole pelvis' },
  { id: 'right', label: 'Right hip' },
  { id: 'left', label: 'Left hip' },
];
export const HIP_GROUPS = [
  'Pelvic bones, joints & ligaments',
  'Hip joint & proximal femur',
  'Gluteal & deep lateral rotators',
  'Anterior hip & iliopsoas region',
  'Medial thigh & adductor origins',
  'Neurovascular & pelvic-floor relations',
  'Clinical surface anatomy',
] as const;
type Group = typeof HIP_GROUPS[number];

/** Appended to every structure that has no individual mesh in the reference model. */
export const INDEX_ONLY = ' Index only — no separate mesh in this reference model.';
const EDU = 'Anatomy learning only; this structure or distribution cannot establish the cause of symptoms.';
const e = (group: Group, id: string, name: string, tissue: Tissue, role: string, relations: string, clinical: string, extra: Partial<StructureInfo> = {}): StructureInfo & { group: Group } =>
  ({ id, name, tissue, role, relations, clinical, group, ...extra });
const io = (group: Group, id: string, name: string, tissue: Tissue, role: string, relations: string, clinical: string, extra: Partial<StructureInfo> = {}) =>
  e(group, id, name, tissue, role, relations + INDEX_ONLY, clinical, extra);
const mu = (group: Group, id: string, name: string, tissue: Tissue, origin: string, insertion: string, innervation: string, role: string, relations: string, clinical: string) =>
  e(group, id, name, tissue, role, relations, clinical, { origin, insertion, innervation });
const GB: Group = 'Pelvic bones, joints & ligaments', GH: Group = 'Hip joint & proximal femur', GG: Group = 'Gluteal & deep lateral rotators', GA: Group = 'Anterior hip & iliopsoas region', GM: Group = 'Medial thigh & adductor origins', GN: Group = 'Neurovascular & pelvic-floor relations', GC: Group = 'Clinical surface anatomy';

export const hipPelvisSpecialist: Region & { intro: string; groups: readonly string[] } = {
  id: 'hip-pelvis', name: 'Hip & Pelvis', groups: HIP_GROUPS,
  intro: 'Bilateral pelvic and hip anatomy from the iliac crests and sacrum to the proximal femora, with whole-pelvis orientation and switchable left/right hip focus. Covers pelvic bones and landmarks, the hip joint and its ligaments, gluteal and deep lateral rotator muscles, the iliopsoas and adductor regions, lumbosacral plexus and iliac/femoral neurovascular relations, and educational surface-anatomy orientation. Pain distributions are anatomy learning, not diagnosis or treatment planning.',
  structures: [
    // ================= Pelvic bones, joints & ligaments =================
    e(GB, 'hip-bone', 'Hip bone (os coxae)', 'bone', 'Fusion of ilium, ischium and pubis at the acetabulum; with the sacrum it forms the pelvic ring transmitting trunk load to the lower limbs.', 'Right and left whole hip-bone meshes shown; ilium, ischium and pubis are regions of the same mesh, not separate parts. The acetabulum sits at the confluence of all three.', 'Pelvic-ring integrity is the central concept in pelvic trauma anatomy — orientation only.', { articulation: 'Sacroiliac joints posteriorly, pubic symphysis anteriorly, hip joint laterally.', attachments: 'Gluteals and abdominal wall to the iliac crest; hamstrings to the ischial tuberosity; adductors to the pubis/ischium; inguinal ligament ASIS to pubic tubercle.' }),
    io(GB, 'ilium', 'Ilium', 'bone', 'Broad superior blade of the hip bone; its crest is the most palpable pelvic landmark.', 'Auricular surface articulates with the sacrum; gluteal surface carries the gluteal lines for gluteus medius/minimus origins. A region of the hip-bone mesh.', EDU, { attachments: 'Gluteus medius/minimus (external surface), iliacus (iliac fossa, internal surface), abdominal wall and latissimus/QL to the crest.' }),
    io(GB, 'ischium', 'Ischium', 'bone', 'Posteroinferior hip-bone element bearing body weight in sitting.', 'Ischial tuberosity (hamstring and sacrotuberous ligament origin), ischial spine (sacrospinous ligament, gemellus superior) and ramus (adductor origins) are regions of the hip-bone mesh.', EDU, { attachments: 'Hamstrings and adductor magnus (tuberosity), sacrospinous ligament and coccygeus (spine), obturator internus (internal surface).' }),
    io(GB, 'pubis', 'Pubis', 'bone', 'Anteromedial hip-bone element; the two pubic bodies meet at the symphysis.', 'Superior ramus carries the pectineal line (pectineus) and pubic tubercle (inguinal ligament); inferior ramus carries adductor and gracilis origins. A region of the hip-bone mesh.', EDU, { attachments: 'Rectus abdominis and pyramidalis (body), pectineus (pecten), adductor longus/brevis and gracilis (rami), inguinal ligament (tubercle).' }),
    io(GB, 'iliac-crest', 'Iliac crest', 'bone', 'Palpable superior border of the ilium from ASIS to PSIS.', 'Anchors the abdominal wall muscles, latissimus dorsi, quadratus lumborum, gluteus medius and the thoracolumbar fascia. The supracristal (Tuffier) line between the highest crest points approximates the L4 spinous process. A landmark on the hip-bone mesh.', 'Classic landmark for lumbar level counting — orientation only.'),
    io(GB, 'asis', 'Anterior superior iliac spine (ASIS)', 'bone', 'Anterior end of the iliac crest; origin of the sartorius and the lateral anchor of the inguinal ligament.', 'Palpable at the front of the hip; the lateral femoral cutaneous nerve passes nearby (usually medial to the ASIS, under or through the inguinal ligament). A landmark on the hip-bone mesh.', 'ASIS tenderness and avulsion patterns are clinical concepts; here it orients the sartorius and inguinal ligament.'),
    io(GB, 'aiis', 'Anterior inferior iliac spine (AIIS)', 'bone', 'Origin of the straight head of the rectus femoris and the iliofemoral ligament region.', 'Just above the acetabular rim; the reflected head of rectus femoris arises above the rim itself. A landmark on the hip-bone mesh.', 'AIIS morphology is discussed in hip impingement anatomy — orientation only.'),
    io(GB, 'psis-piis', 'PSIS & PIIS', 'bone', 'Posterior superior and inferior iliac spines; the PSIS dimple overlies the S2 level and the SI joint.', 'PSIS anchors the oblique part of the posterior SI ligaments and the thoracolumbar fascia; PIIS marks the inferior end of the auricular surface. Landmarks on the hip-bone mesh.', 'The Fortin finger region (within ~1 cm of the PSIS) is a described SI examination association — orientation only.'),
    io(GB, 'ischial-spine', 'Ischial spine', 'bone', 'Pointed posterior ischial projection separating the greater and lesser sciatic notches.', 'Attachment for the sacrospinous ligament and coccygeus; the pudendal nerve and internal pudendal vessels pass immediately medial to it between the sacrotuberous and sacrospinous ligaments. A landmark on the hip-bone mesh.', 'Key relation for pudendal pathway anatomy — orientation only.'),
    io(GB, 'ischial-tuberosity', 'Ischial tuberosity', 'bone', 'The "sitting bone"; common hamstring origin and sacrotuberous ligament attachment.', 'Semitendinosus, semimembranosus and the long head of biceps femoris share the proximal impression; adductor magnus (ischiocondylar part) arises below. A landmark on the hip-bone mesh.', 'Proximal hamstring and ischial bursa anatomy localizes here — orientation only.'),
    io(GB, 'pubic-tubercle', 'Pubic tubercle & crest', 'bone', 'Small anterior projection on the superior pubic ramus; medial anchor of the inguinal ligament.', 'The inguinal ligament runs ASIS to pubic tubercle; the conjoint tendon and rectus abdominis attach nearby. A landmark on the hip-bone mesh.', 'Surface reference for the femoral pulse point just below the inguinal ligament midpoint — orientation only.'),
    io(GB, 'obturator-foramen', 'Obturator foramen', 'bone', 'Large opening bounded by the pubis and ischium, closed by the obturator membrane except at the obturator canal superolaterally.', 'The obturator nerve, artery and vein pass through the obturator canal from pelvis to medial thigh. The foramen is a region of the hip-bone mesh; the membrane is a separate mesh.', 'Obturator hernia anatomy relates to the canal — orientation only.'),
    e(GB, 'sacrum', 'Sacrum', 'bone', 'Five fused vertebrae forming the posterior pelvic wall; keystone of the pelvic ring.', 'Single mesh with the median sacral crest, sacral foramina (anterior/posterior rami exit) and the sacral hiatus inferiorly. Covered in detail in the Back & Spine module.', EDU, { articulation: 'L5 above, ilia at the SI joints, coccyx below.', attachments: 'Posterior SI ligaments, sacrotuberous/sacrospinous ligaments, gluteus maximus, piriformis (anterior surface), pelvic floor.' }),
    e(GB, 'coccyx', 'Coccyx & sacrococcygeal junction', 'bone', 'Three to five fused rudimentary vertebrae; attachment for the pelvic floor and anococcygeal ligament.', 'Coccyx and sacrococcygeal symphysis meshes shown; gluteus maximus and the levator ani complex attach here.', EDU, { articulation: 'Sacrococcygeal symphysis (fibrocartilaginous).' }),
    e(GB, 'si-joint', 'Sacroiliac joint & ligaments', 'ligament', 'Auricular synovial joint (anteroinferior) plus the strongest syndesmosis in the body posteriorly; transfers load between spine and lower limb with a few degrees of nutation.', 'Anterior, interosseous and posterior sacro-iliac ligament meshes shown bilaterally; the interosseous ligament fills the tuberosity gap behind the auricular surfaces.', 'SI-region pain localizes near the PSIS; provocation clusters exist clinically — anatomy orientation only.', { articulation: 'Sacral and iliac auricular surfaces.', attachments: 'Interosseous and posterior SI ligaments bind sacrum to ilium; anterior SI ligament is a thin capsular thickening.' }),
    e(GB, 'pubic-symphysis', 'Pubic symphysis & pubic ligaments', 'fibrocartilage', 'Midline fibrocartilaginous joint uniting the pubic bodies; permits small shear and rotation movements.', 'Pubic symphysis, interpubic disc, and superior and inferior pubic ligament meshes shown; the disc may contain a small cavity. The arcuate (inferior) ligament rounds the subpubic angle.', 'Symphyseal widening and stress reactions are clinical concepts; here it completes the anterior pelvic ring.', { articulation: 'Interpubic fibrocartilage between the pubic bodies.', attachments: 'Superior pubic ligament across the pubic crests; inferior (arcuate) pubic ligament below; rectus abdominis blends anteriorly.' }),
    e(GB, 'sacro-ligs', 'Sacrotuberous & sacrospinous ligaments', 'ligament', 'Convert the sciatic notches into the greater and lesser sciatic foramina; resist nutation of the sacrum.', 'Both shown bilaterally: sacrotuberous (PSIS/sacrum to ischial tuberosity) is superficial; sacrospinous (sacrum/coccyx to ischial spine) lies deep, partly blended with coccygeus.', 'They bound the pathways of the sciatic nerve (greater foramen) and pudendal nerve (between the two, around the ischial spine) — orientation only.', { attachments: 'Sacrotuberous: PSIS, posterior sacrum and coccyx to the ischial tuberosity. Sacrospinous: lateral sacrum/coccyx to the ischial spine.' }),
    e(GB, 'iliolumbar', 'Iliolumbar ligament', 'ligament', 'Anchors the L5 (and L4) transverse process to the iliac crest, stabilizing the lumbosacral junction onto the pelvis.', 'Right and left meshes shown; blends with the anterior SI ligament and quadratus lumborum fascia. Also mapped in the Back & Spine module.', 'A candidate structure in lumbosacral strain discussions — orientation only.', { attachments: 'Tip of the L5 transverse process to the inner lip of the iliac crest.' }),
    e(GB, 'obturator-membrane', 'Obturator membrane', 'fascia', 'Fibrous sheet closing the obturator foramen; origin surface for the obturator internus (pelvic surface) and externus (outer surface).', 'Right and left meshes shown; the superolateral obturator canal remains open for the obturator nerve and vessels.', EDU, { attachments: 'Margins of the obturator foramen; continuous with obturator fascia.' }),
    e(GB, 'inguinal-lig', 'Inguinal ligament', 'ligament', 'Rolled inferior edge of the external oblique aponeurosis from ASIS to pubic tubercle; the boundary between abdomen and thigh.', 'Right and left meshes shown. The femoral nerve, artery and vein pass beneath it in the femoral triangle (nerve most lateral), and the iliopsoas passes deep to it in the muscular lacuna.', 'Its midpoint (mid-inguinal point) approximates the femoral artery surface position — landmark orientation only.', { attachments: 'ASIS laterally to the pubic tubercle medially; lacunar ligament reflects to the pectineal line.' }),

    // ================= Hip joint & proximal femur =================
    e(GH, 'femur-proximal', 'Femur — proximal region', 'bone', 'Longest bone in the body; the proximal femur forms the ball of the hip joint and the lever for the gluteal and short rotator muscles.', 'Right and left whole-femur meshes shown, cropped to the proximal third in this module; head, neck and trochanters are landmarks on the same mesh.', 'Femoral neck and intertrochanteric fracture patterns are core clinical anatomy; here the femur orients every hip muscle insertion.', { articulation: 'Head with the acetabulum (hip joint); shaft continues to the knee (future module).', attachments: 'Gluteus medius/minimus (greater trochanter), iliopsoas (lesser trochanter), piriformis and obturator/gemelli group (trochanteric crest/fossa), quadratus femoris (quadrate tubercle), gluteus maximus (gluteal tuberosity).' }),
    io(GH, 'femoral-head', 'Femoral head', 'bone', 'Two-thirds of a sphere covered in hyaline cartilage except at the fovea, where the ligament of the head attaches.', 'Blood supply arrives via the retinacular branches of the medial femoral circumflex artery ascending the neck — the anatomical basis of avascular-necrosis risk after neck fracture. A region of the femur mesh.', 'The medial circumflex femoral artery relation explains why intracapsular neck fractures threaten head perfusion — orientation only.'),
    io(GH, 'femoral-neck', 'Femoral neck', 'bone', 'Connects head to shaft at the neck-shaft angle (~125°); intracapsular, bathed in synovial fluid.', 'The retinacular vessels run along its posterosuperior surface; the calcar femorale is the dense medial trabecular strut. A region of the femur mesh.', 'Intracapsular vs extracapsular fracture location drives the perfusion concept above — orientation only.'),
    io(GH, 'greater-trochanter', 'Greater trochanter', 'bone', 'Large lateral projection at the neck-shaft junction; the "hip bone" felt on the outer thigh.', 'Gluteus medius inserts on the lateral facet, gluteus minimus on the anterior facet; trochanteric bursae of both muscles separate them from the bone, and the gluteus maximus bursa lies more superficially. A landmark on the femur mesh.', 'Lateral hip tenderness over the trochanter maps to the gluteal tendon/bursa region — orientation only.'),
    io(GH, 'lesser-trochanter', 'Lesser trochanter', 'bone', 'Posteromedial projection at the base of the neck; the insertion of the iliopsoas tendon.', 'The iliacus and psoas major converge on it as the conjoint iliopsoas tendon. A landmark on the femur mesh.', 'Isolated lesser-trochanter avulsion is a recognized clinical pattern — orientation only.'),
    io(GH, 'intertrochanteric', 'Intertrochanteric line & crest', 'bone', 'Anterior line (iliofemoral ligament attachment) and posterior crest (quadratus femoris and short rotator attachments) between the trochanters.', 'The intertrochanteric region is extracapsular anteriorly at the line and posteriorly beyond the crest — the capsule attaches to the line in front but only partway up the neck behind. Landmarks on the femur mesh.', 'The capsular attachment asymmetry explains which neck fractures are intracapsular — orientation only.'),
    e(GH, 'hip-capsule', 'Articular capsule of the hip joint', 'capsule', 'Strong fibrous sleeve from the acetabular rim to the intertrochanteric line (anteriorly) and mid-neck (posteriorly); encloses the femoral head and most of the neck.', 'Right and left capsule meshes shown; the iliofemoral, pubofemoral and ischiofemoral ligaments are its named thickenings. The zona orbicularis (circular fibres) collars the neck.', 'Capsular anatomy frames hip joint pain patterns (groin-dominant) — orientation only.', { attachments: 'Acetabular rim and transverse acetabular ligament to the intertrochanteric line and neck.' }),
    e(GH, 'labrum', 'Acetabular labrum', 'fibrocartilage', 'Fibrocartilaginous rim deepening the acetabulum and maintaining the suction seal of the hip joint.', 'Right and left labrum meshes shown; continuous inferiorly with the transverse acetabular ligament across the acetabular notch. The labrum is poorly vascularized at its articular margin.', 'Labral tear anatomy relates to groin pain and mechanical symptoms — orientation only.', { articulation: 'Attached to the acetabular rim; blends with the transverse acetabular ligament.' }),
    e(GH, 'transverse-acetabular', 'Transverse acetabular ligament', 'ligament', 'Bridges the acetabular notch, completing the socket inferiorly; the notch below it transmits vessels into the joint.', 'Right and left meshes shown; continuous with the labrum at both ends of the notch.', EDU, { attachments: 'Across the acetabular notch between the two limbs of the acetabular rim.' }),
    e(GH, 'lig-head-femur', 'Ligament of the head of the femur', 'ligament', 'Intra-articular ligament from the transverse acetabular ligament/acetabular notch to the fovea of the femoral head.', 'Right and left meshes shown; carries the foveal artery (branch of the obturator artery), a minor head supply in adults but significant in children.', EDU, { attachments: 'Acetabular notch and transverse ligament to the fovea capitis.' }),
    e(GH, 'iliofemoral', 'Iliofemoral ligament (Y-ligament of Bigelow)', 'ligament', 'Strongest ligament in the body; inverted-Y anterior capsular thickening resisting hyperextension and maintaining upright posture with minimal muscle effort.', 'Descending and transverse parts shown bilaterally as separate meshes; from the AIIS region to the intertrochanteric line.', EDU, { attachments: 'AIIS and acetabular rim to the upper (transverse part) and lower (descending part) intertrochanteric line.' }),
    e(GH, 'pubofemoral', 'Pubofemoral ligament', 'ligament', 'Anteroinferior capsular thickening limiting abduction and extension.', 'Right and left meshes shown; from the superior pubic ramus/iliopectineal region blending into the descending iliofemoral band and capsule.', EDU, { attachments: 'Superior pubic ramus and obturator crest region to the anterior capsule/intertrochanteric line.' }),
    e(GH, 'ischiofemoral', 'Ischiofemoral ligament', 'ligament', 'Posterior capsular thickening spiralling from the ischial acetabular rim over the neck; limits extension and internal rotation.', 'Right and left meshes shown; the weakest of the three capsular ligaments, leaving the posteriorinferior capsule relatively thin.', 'Posterior capsule anatomy relates to posterior dislocation patterns — orientation only.', { attachments: 'Ischial part of the acetabular rim, spiralling laterally to the neck/greater trochanter region.' }),
    io(GH, 'hip-cartilage', 'Acetabular & femoral articular cartilage', 'cartilage', 'Hyaline cartilage of the lunate surface of the acetabulum and the femoral head; thickest where load is greatest.', 'The lunate surface is horseshoe-shaped around the acetabular fossa (filled with the pulvinar fat pad); cartilage is not segmented as a separate mesh.', 'Cartilage wear patterns underlie osteoarthritis anatomy — orientation only.', { articulation: 'Load-bearing interface of the hip joint.' }),

    // ================= Gluteal & deep lateral rotators =================
    mu(GG, 'gluteus-maximus', 'Gluteus maximus', 'muscleSuperficial', 'Posterior ilium behind the posterior gluteal line, posterior sacrum and coccyx, sacrotuberous ligament and thoracolumbar fascia.', 'Iliotibial tract (upper and most fibres) and gluteal tuberosity of the femur (deep lower fibres).', 'Inferior gluteal nerve (L5–S2).', 'Powerful hip extensor and lateral rotator; acts from flexion (rising, climbing, running) rather than in quiet standing.', 'Largest and most superficial gluteal muscle; the sciatic nerve and deep rotators lie deep to it; the sciatic bursa separates it from the ischial tuberosity.', 'Its iliotibial-tract insertion links hip extension to lateral knee stability.'),
    mu(GG, 'gluteus-medius', 'Gluteus medius', 'muscleSuperficial', 'External surface of the ilium between the anterior and posterior gluteal lines.', 'Lateral facet of the greater trochanter.', 'Superior gluteal nerve (L4–S1).', 'Abducts the hip; anterior fibres assist flexion and medial rotation, posterior fibres extension and lateral rotation. Its frontal-plane hold of the pelvis is the key single-leg-stance function.', 'Deep to gluteus maximus posteriorly, superficial to gluteus minimus; its trochanteric bursa lies at the insertion.', 'Medius/minimus weakness anatomy underlies the Trendelenburg sign concept — orientation only.'),
    mu(GG, 'gluteus-minimus', 'Gluteus minimus', 'muscleDeep', 'External surface of the ilium between the anterior and inferior gluteal lines.', 'Anterior facet of the greater trochanter.', 'Superior gluteal nerve (L4–S1).', 'Abducts and medially rotates the hip; with medius, stabilizes the pelvis in single-leg stance.', 'Deepest gluteal muscle, lying on the capsule; the superior gluteal nerve and vessels run between medius and minimus.', 'Shares the superior gluteal nerve with medius and TFL — one lesion affects the whole abductor group.'),
    mu(GG, 'tfl', 'Tensor fasciae latae', 'muscleSuperficial', 'Anterior iliac crest and outer lip of the ASIS.', 'Iliotibial tract (which continues to the Gerdy tubercle of the tibia).', 'Superior gluteal nerve (L4–S1).', 'Flexes, abducts and medially rotates the hip; tensions the iliotibial tract to stabilize the extended knee.', 'Small muscle enclosed between the two layers of the fascia lata at the anterolateral hip; the tract it feeds is a separate mesh.', 'TFL–IT tract tension anatomy is discussed in lateral hip and knee pain maps — orientation only.'),
    e(GG, 'it-tract', 'Iliotibial tract', 'fascia', 'Thickened lateral band of the fascia lata receiving gluteus maximus and tensor fasciae latae insertions.', 'Right and left meshes shown, cropped below the hip in this module; proximally it overlies the greater trochanter and vastus lateralis.', 'The tract is a tension band linking the pelvis to the lateral knee — its proximal relations are the focus here.', { attachments: 'Iliac crest (via fascia lata) to the Gerdy tubercle; receives TFL and most of gluteus maximus.' }),
    mu(GG, 'piriformis', 'Piriformis', 'muscleDeep', 'Anterior surface of the sacrum (S2–S4), sacrotuberous ligament and the ilium near the PIIS.', 'Superior border of the greater trochanter.', 'Nerve to piriformis (S1–S2, separate mesh).', 'Lateral rotator of the extended hip, abductor of the flexed hip.', 'Exits the pelvis through the greater sciatic foramen, dividing it into suprapiriform (superior gluteal nerve/vessels) and infrapiriform (sciatic nerve, inferior gluteal and pudendal structures) parts. Piriformis fascia and bursa are separate meshes.', 'The infrapiriform sciatic nerve relation is the anatomical basis of deep gluteal space discussions — orientation only.'),
    mu(GG, 'obturator-internus', 'Obturator internus', 'muscleDeep', 'Internal (pelvic) surface of the obturator membrane and the surrounding bone.', 'Medial surface of the greater trochanter (with the gemelli).', 'Nerve to obturator internus (L5–S1).', 'Lateral rotator of the extended hip, abductor of the flexed hip; its intrapelvic portion also supports the pelvic wall.', 'Its tendon makes a right-angle turn around the lesser sciatic notch (cushioned by the sciatic bursa of obturator internus, a separate mesh) and is joined by the gemelli. The obturator fascia over it anchors the tendinous arch of levator ani.', 'The tendon groove at the lesser sciatic notch is a key deep gluteal landmark — orientation only.'),
    mu(GG, 'obturator-externus', 'Obturator externus', 'muscleDeep', 'External surface of the obturator membrane and adjacent pubis/ischium.', 'Trochanteric fossa of the femur.', 'Obturator nerve (posterior branch, L3–L4).', 'Lateral rotator of the hip; assists adduction.', 'Lies deep on the anterior-inferior capsule, passing under the femoral neck; the obturator nerve anterior branch crosses it.', 'Deep anterior hip relation rarely seen except in deep dissection — orientation only.'),
    mu(GG, 'gemelli', 'Superior & inferior gemelli', 'muscleDeep', 'Superior: ischial spine. Inferior: ischial tuberosity (upper part).', 'Both join the obturator internus tendon to the medial greater trochanter.', 'Superior: nerve to obturator internus (L5–S1). Inferior: nerve to quadratus femoris (L4–S1).', 'Assist the obturator internus in lateral rotation; considered its marginal helpers.', 'Separate right and left meshes shown above and below the obturator internus tendon, between piriformis and quadratus femoris.', 'Part of the "deep six" lateral rotator group bounding the deep gluteal space.'),
    mu(GG, 'quadratus-femoris', 'Quadratus femoris', 'muscleDeep', 'Lateral border of the ischial tuberosity.', 'Quadrate tubercle on the intertrochanteric crest and the area below it.', 'Nerve to quadratus femoris (L4–S1, separate mesh).', 'Strong lateral rotator of the hip; assists adduction.', 'Lowest of the deep rotators, a flat quadrilateral sheet; the sciatic nerve crosses its anterior surface, and the medial circumflex femoral artery passes between it and obturator externus.', 'Ischiofemoral-space anatomy (between quadratus femoris and the ischium/trochanter) is discussed in posterior hip pain literature — orientation only.'),
    e(GG, 'trochanteric-bursae', 'Trochanteric bursae (gluteus maximus, medius & minimus)', 'bursa', 'Friction-reducing sacs at the greater trochanter: maximus bursa between the gluteus maximus/IT tract and the trochanter, medius and minimus bursae beneath their tendons.', 'Trochanteric bursae of gluteus maximus, medius and minimus, the subcutaneous trochanteric bursa and the intermuscular gluteal bursae are separate bilateral meshes.', 'Lateral hip pain maps to this bursal/tendon complex — anatomy orientation only, not a bursitis diagnosis.', { attachments: 'Between the gluteal tendons, iliotibial tract and the greater trochanter facets.' }),
    e(GG, 'sciatic-bursae', 'Sciatic bursae (gluteus maximus & obturator internus)', 'bursa', 'The gluteus maximus sciatic bursa cushions the ischial tuberosity in sitting; the obturator internus sciatic bursa cushions its tendon at the lesser sciatic notch.', 'Both shown bilaterally as separate meshes.', 'Ischial-region pain in sitting localizes to the tuberosity/bursa region — orientation only.', { attachments: 'Ischial tuberosity (maximus) and lesser sciatic notch (obturator internus).' }),
    io(GG, 'deep-rotator-concept', 'Deep lateral rotator group — organization', 'space', 'Piriformis, obturator internus with the gemelli, and quadratus femoris form the "deep six" (with obturator externus anteriorly), stacked between the piriformis and the ischial tuberosity.', 'From above down: piriformis, superior gemellus, obturator internus tendon, inferior gemellus, quadratus femoris — the sciatic nerve descends across this stack. Each member has its own entry and mesh; this overview has none.', 'The stacked relation to the sciatic nerve organizes deep gluteal space anatomy.'),

    // ================= Anterior hip & iliopsoas region =================
    mu(GA, 'psoas', 'Psoas major', 'muscleDeep', 'Transverse processes, bodies and discs of T12–L5.', 'Lesser trochanter of the femur (with iliacus as the iliopsoas).', 'Ventral rami of L1–L3 (direct branches).', 'Chief hip flexor; lumbar lateral flexor; stabilizes the lumbar spine in sitting and standing.', 'Descends in the posterior abdominal wall (the lumbar plexus forms within it), passes under the inguinal ligament in the muscular lacuna lateral to the femoral vessels. Also mapped in the Back & Spine module.', 'The lumbar-plexus-in-psoas relation explains anterior thigh symptoms from psoas-region pathology — orientation only.'),
    mu(GA, 'iliacus', 'Iliacus', 'muscleDeep', 'Iliac fossa, inner lip of the iliac crest, anterior sacro-iliac and iliolumbar ligaments and the sacral ala.', 'Lesser trochanter and the psoas tendon (conjoint iliopsoas), with fibres to the capsule below.', 'Femoral nerve (L2–L3).', 'Hip flexion; with psoas, the strongest flexor of the thigh on the trunk or the trunk on the thigh (sit-up).', 'Fills the iliac fossa lateral to psoas; the femoral nerve runs in the groove between them under the iliacus fascia. The subtendinous bursa of iliacus (separate mesh) lies at the insertion.', 'The femoral nerve lies on its surface — the key anterior-hip neurovascular relation.'),
    e(GA, 'iliopsoas-fascia', 'Iliopsoas fascia & iliacus bursa', 'fascia', 'Fascial envelope of the psoas and iliacus continuous with the thoracolumbar fascia above and the pectineal fascia below; the subtendinous bursa of iliacus cushions the tendon at the lesser trochanter and may communicate with the hip joint.', 'Iliopsoas fascia and subtendinous bursa of iliacus shown bilaterally as separate meshes.', 'A communicating bursa can outline the anterior hip joint on imaging — orientation only.', { attachments: 'Iliac fascia lines the iliac fossa; psoas fascia blends with the arcuate ligaments and pelvic brim.' }),
    mu(GA, 'rectus-femoris', 'Rectus femoris — origin region', 'muscleSuperficial', 'Straight head from the AIIS; reflected head from the ilium above the acetabular rim and the capsule.', 'Quadriceps tendon to the patella (distal course outside this module).', 'Femoral nerve (L2–L4).', 'Flexes the hip and extends the knee; the only quadriceps part crossing the hip.', 'Whole-muscle mesh shown, cropped to its origin region in this module; the straight and reflected heads frame the AIIS and acetabular rim.', 'Rectus origin strain and AIIS avulsion are classic athlete anatomy — orientation only.'),
    mu(GA, 'sartorius', 'Sartorius — origin region', 'muscleSuperficial', 'ASIS and the notch just below it.', 'Medial surface of the proximal tibia (pes anserinus, distal course outside this module).', 'Femoral nerve (L2–L3).', 'Flexes, abducts and laterally rotates the hip (the "tailor" position) with knee flexion.', 'Longest muscle in the body; its origin at the ASIS forms the lateral boundary of the femoral triangle. Mesh cropped to the proximal thigh here.', 'The lateral femoral cutaneous nerve passes near its ASIS origin — a surface-anatomy relation.'),
    mu(GA, 'pectineus', 'Pectineus', 'muscleDeep', 'Pectineal line (pecten) of the superior pubic ramus.', 'Pectineal line of the femur, from the lesser trochanter to the linea aspera.', 'Femoral nerve (L2–L3), sometimes an obturator branch.', 'Flexes and adducts the hip.', 'Flat quadrangular muscle forming part of the floor of the femoral triangle, between iliopsoas (lateral) and adductor longus (medial).', 'Boundary muscle of the femoral triangle — surface orientation.'),
    io(GA, 'femoral-triangle', 'Femoral triangle', 'space', 'Subinguinal space bounded by the inguinal ligament (base), sartorius (lateral) and adductor longus (medial); floor of iliopsoas and pectineus.', 'Contents lateral to medial: femoral nerve, femoral artery, femoral vein, (empty space/lymphatics) — "NAVY". The nerve lies outside the femoral sheath; artery and vein within it. A conceptual region without its own mesh.', 'The mid-inguinal point (below the inguinal ligament midpoint) is the classic femoral pulse landmark — orientation only.'),
    io(GA, 'iliopectineal', 'Iliopectineal arch & lacunae', 'fascia', 'Fascial thickening from the inguinal ligament to the iliopectineal eminence dividing the subinguinal passage into the muscular lacuna (iliopsoas and femoral nerve, lateral) and vascular lacuna (femoral vessels, medial).', 'Not separately segmented; the inguinal ligament mesh marks the superficial boundary.', 'The lacunar arrangement explains why the femoral nerve lies outside the femoral sheath — orientation only.'),

    // ================= Medial thigh & adductor origins =================
    mu(GM, 'adductor-longus', 'Adductor longus', 'muscleSuperficial', 'Anterior body of the pubis just below the pubic crest.', 'Middle third of the linea aspera of the femur.', 'Obturator nerve (anterior branch, L2–L4).', 'Adducts and assists flexion of the hip.', 'Most anterior adductor; its tendon is palpable in the groin and forms the medial boundary of the femoral triangle.', 'The palpable adductor longus tendon is the classic groin-strain landmark — orientation only.'),
    mu(GM, 'adductor-brevis', 'Adductor brevis', 'muscleDeep', 'Anterior body and inferior ramus of the pubis.', 'Pectineal line and proximal linea aspera of the femur.', 'Obturator nerve (anterior branch, L2–L4).', 'Adducts and assists flexion of the hip.', 'Lies behind pectineus and adductor longus; the anterior branch of the obturator nerve descends on its anterior surface, the posterior branch behind it.', 'The obturator nerve branches sandwiching it are a dissection landmark.'),
    mu(GM, 'adductor-magnus', 'Adductor magnus', 'muscleDeep', 'Inferior pubic ramus, ischial ramus and ischial tuberosity.', 'Linea aspera, medial supracondylar line and adductor tubercle (distal course outside this module).', 'Obturator nerve (posterior branch) for the adductor part; tibial division of the sciatic nerve for the hamstring (ischiocondylar) part.', 'Powerful adductor; the posterior (hamstring) part also extends the hip.', 'Largest and deepest adductor with a dual nerve supply reflecting its composite origin; its proximal fibres lie directly behind the hip capsule region.', 'Dual innervation is the classic exam point — obturator plus sciatic (tibial).'),
    mu(GM, 'adductor-minimus', 'Adductor minimus', 'muscleDeep', 'Inferior pubic ramus (superior part of adductor magnus origin).', 'Medial lip of the linea aspera, proximal part.', 'Obturator nerve (posterior branch, L2–L4).', 'Adducts and laterally rotates the hip.', 'The separated superior part of adductor magnus, exported as its own bilateral mesh in this reference model.', 'Often described as part of adductor magnus; here it is a distinct mesh.'),
    mu(GM, 'gracilis', 'Gracilis — origin region', 'muscleSuperficial', 'Body and inferior ramus of the pubis near the symphysis.', 'Medial surface of the proximal tibia (pes anserinus, distal course outside this module).', 'Obturator nerve (anterior branch, L2–L3).', 'Adducts the hip and flexes/medially rotates the knee.', 'Most medial and superficial adductor, a thin strap along the inner thigh; mesh cropped proximally here.', 'Its pubic origin completes the adductor mass palpable in the medial groin.'),
    mu(GM, 'hamstring-origins', 'Hamstring origins (semitendinosus, semimembranosus, long head of biceps femoris)', 'muscleDeep', 'Common origin from the ischial tuberosity impression (semitendinosus with the long head of biceps via a conjoint tendon; semimembranosus from the superolateral impression).', 'Tibia and fibular head (distal courses outside this module).', 'Tibial division of the sciatic nerve (L5–S2).', 'Extend the hip and flex the knee; the long head of biceps femoris is the only biceps part crossing the hip.', 'Three separate bilateral meshes shown, cropped to their proximal third; the sciatic nerve lies lateral to the semimembranosus origin at the tuberosity.', 'Proximal hamstring anatomy localizes to the ischial tuberosity — orientation only.'),
    mu(GM, 'vastus-origins', 'Vastus lateralis, medialis & intermedius — proximal relations', 'muscleDeep', 'Vastus lateralis: greater trochanter and lateral lip of the linea aspera. Vastus medialis: intertrochanteric line and medial lip. Vastus intermedius: anterior and lateral femoral shaft.', 'Quadriceps tendon to the patella (outside this module).', 'Femoral nerve (L2–L4).', 'Knee extension; none cross the hip, but their origins frame the proximal femur.', 'Three separate bilateral meshes cropped to the proximal thigh; vastus lateralis origin overlaps the gluteus medius/minimus insertion region at the trochanter.', 'The vastus origin region is part of the lateral hip surgical corridor — orientation only.'),
    io(GM, 'adductor-compartment', 'Medial compartment organization', 'space', 'Layered arrangement: gracilis (most medial), adductor longus (anterior), adductor brevis (middle), adductor magnus (posterior/deep), with obturator externus superiorly.', 'The anterior branch of the obturator nerve runs between longus and brevis; the posterior branch between brevis and magnus — a clean dissection rule. A conceptual grouping without its own mesh.', 'The nerve-layer rule orients every adductor entry in this module.'),

    // ================= Neurovascular & pelvic-floor relations =================
    e(GN, 'sciatic', 'Sciatic nerve', 'nerve', 'Largest nerve in the body (L4–S3); tibial and common fibular divisions usually share one sheath to the popliteal fossa.', 'Exits the pelvis through the greater sciatic foramen below the piriformis, descends between the greater trochanter and ischial tuberosity on the obturator internus/gemelli and quadratus femoris, deep to gluteus maximus. Right and left meshes shown.', 'Its infrapiriform course is the key deep gluteal relation; the posterior-approach danger structure — orientation only.', { course: 'Sacral plexus → greater sciatic foramen (infrapiriform) → deep gluteal space → posterior thigh.', supplies: 'Hamstrings, adductor magnus (hamstring part), and everything below the knee via its divisions.' }),
    e(GN, 'sup-gluteal-n', 'Superior gluteal nerve', 'nerve', 'Motor nerve of the abductor group (L4–S1).', 'Exits above the piriformis (suprapiriform foramen) with the superior gluteal vessels and runs between gluteus medius and minimus. Right and left meshes shown.', 'Its lesion weakens abduction — the Trendelenburg anatomy concept.', { course: 'Sacral plexus → greater sciatic foramen above piriformis → between gluteus medius and minimus.', supplies: 'Gluteus medius, gluteus minimus, tensor fasciae latae.' }),
    io(GN, 'inf-gluteal-n', 'Inferior gluteal nerve', 'nerve', 'Motor nerve of gluteus maximus (L5–S2).', 'Exits below the piriformis medial to the sciatic nerve and enters the deep surface of gluteus maximus. Not exported as an individual mesh in this reference model.', 'Gluteus maximus denervation anatomy relates to hip extension power — orientation only.', { supplies: 'Gluteus maximus.' }),
    e(GN, 'deep-rotator-nerves', 'Nerves to piriformis, obturator internus & quadratus femoris', 'nerve', 'Small direct branches of the sacral plexus: nerve to piriformis (S1–S2), nerve to obturator internus (L5–S1, also superior gemellus) and nerve to quadratus femoris (L4–S1, also inferior gemellus and the hip joint).', 'Nerve to piriformis and nerve to quadratus femoris are separate bilateral meshes; the nerve to obturator internus is not individually exported. The nerve to quadratus femoris gives an articular branch to the hip capsule.', 'Articular branches explain hip-joint sensory innervation from the deep gluteal side — orientation only.', { supplies: 'Piriformis; obturator internus and superior gemellus; quadratus femoris, inferior gemellus and hip joint.' }),
    e(GN, 'pudendal', 'Pudendal nerve', 'nerve', 'Chief nerve of the perineum (S2–S4).', 'Exits the greater sciatic foramen medial to the sciatic nerve, crosses the ischial spine/sacrospinous ligament, then re-enters the pelvis through the lesser sciatic foramen to the pudendal canal. Right and left meshes shown.', 'Its ischial-spine relation is the landmark for pudendal pathway anatomy — orientation only.', { course: 'Sacral plexus → greater sciatic foramen → ischial spine → lesser sciatic foramen → pudendal (Alcock) canal.', supplies: 'Perineal skin and muscles, external anal sphincter, external genitalia.' }),
    e(GN, 'pfcn', 'Posterior femoral cutaneous nerve', 'nerve', 'Sensory nerve of the posterior thigh and lower buttock (S1–S3), including the inferior cluneal branches.', 'Exits below the piriformis medial to the sciatic nerve, descends under gluteus maximus then superficially down the posterior thigh. Nerve and its anterior/posterior roots are separate bilateral meshes.', 'Its inferior cluneal branches supply the lower buttock fold — surface orientation.', { course: 'Sacral plexus → infrapiriform foramen → deep to gluteus maximus → posterior thigh fascia.', supplies: 'Skin of the posterior thigh, lower buttock (inferior cluneal) and perineal edge.' }),
    e(GN, 'lfcn', 'Lateral femoral cutaneous nerve', 'nerve', 'Purely sensory nerve of the lateral thigh (L2–L3).', 'Crosses the iliacus, then passes under or through the inguinal ligament near the ASIS (usually ~1 cm medial) into the lateral thigh. Right and left meshes shown.', 'Its ASIS/inguinal-ligament passage is the classic entrapment-site anatomy (meralgia paresthetica concept) — orientation only.', { course: 'Lumbar plexus → across iliacus → under inguinal ligament near ASIS → lateral thigh skin.', supplies: 'Skin of the anterolateral thigh to the knee.' }),
    e(GN, 'femoral-n', 'Femoral nerve', 'nerve', 'Largest branch of the lumbar plexus (L2–L4); motor to the quadriceps and hip flexors, sensory to the anterior thigh and medial leg.', 'Forms within psoas, emerges in the groove between psoas and iliacus under the iliacus fascia, passes under the inguinal ligament lateral to the femoral artery (outside the femoral sheath) and divides in the femoral triangle. Nerve and anterior cutaneous branches are separate bilateral meshes.', 'The NAVL relation (nerve–artery–vein–lymphatics, lateral to medial) is the triangle landmark rule.', { course: 'Lumbar plexus → psoas/iliacus groove → muscular lacuna → femoral triangle branches.', supplies: 'Iliacus, pectineus, sartorius, quadriceps; anterior thigh skin; saphenous nerve to the medial leg.' }),
    e(GN, 'obturator-n', 'Obturator nerve & branches', 'nerve', 'Motor nerve of the adductor compartment (L2–L4) with sensory branches to the medial thigh and hip/knee joints.', 'Descends along the lateral pelvic wall, passes through the obturator canal with the obturator vessels, then splits into anterior (between adductor longus and brevis) and posterior (between brevis and magnus) branches. Nerve and both branches are separate bilateral meshes.', 'Its hip articular branch is one route of hip-to-knee referred pain anatomy — orientation only.', { course: 'Lumbar plexus → lateral pelvic wall → obturator canal → anterior/posterior branches in the medial thigh.', supplies: 'Adductor longus, brevis, magnus (adductor part), gracilis, obturator externus; medial thigh skin; hip and knee joints.' }),
    e(GN, 'genitofemoral', 'Genitofemoral & ilio-inguinal nerves', 'nerve', 'Genitofemoral (L1–L2) pierces psoas to its anterior surface, splitting into genital and femoral branches; ilio-inguinal (L1) crosses the iliacus toward the inguinal canal.', 'Genitofemoral nerve with femoral and genital branches, and the ilio-inguinal nerve, are separate bilateral meshes.', 'Upper-groin sensory anatomy relates to these L1–L2 branches — orientation only.', { course: 'Lumbar plexus → psoas anterior surface (genitofemoral) / across quadratus lumborum and iliacus (ilio-inguinal) → inguinal region.', supplies: 'Femoral triangle skin (femoral branch); genital region and cremaster (genital branch); inguinal skin (ilio-inguinal).' }),
    e(GN, 'common-iliac', 'Common iliac artery & vein', 'artery', 'Terminal branches of the aorta (and IVC tributaries) at the L4 level, diverging around the sacroiliac joint.', 'Right and left artery and vein meshes shown; each divides into external (to the limb) and internal (to the pelvis) iliac vessels anterior to the SI joint.', 'The bifurcation overlies the SI joint — a pelvic vascular landmark.', { course: 'Aortic bifurcation (~L4) → common iliac → external and internal iliac at the pelvic brim.' }),
    e(GN, 'external-iliac', 'External iliac artery & vein', 'artery', 'Continuation of the common iliac along the pelvic brim; becomes the femoral artery behind the inguinal ligament.', 'Right and left artery and vein meshes shown; the vein lies medial to the artery. No major branches except the inferior epigastric and deep circumflex iliac near the ligament.', 'The external-to-femoral transition at the inguinal ligament is the surface landmark for the femoral pulse.', { course: 'Pelvic brim → along the psoas/iliopectineal line → under the inguinal ligament (vascular lacuna) → femoral vessels.' }),
    e(GN, 'internal-iliac', 'Internal iliac artery & vein', 'artery', 'Supply of the pelvic walls, pelvic viscera, perineum and gluteal region; divides into anterior and posterior divisions.', 'Internal iliac artery and vein plus anterior and posterior divisions shown bilaterally; the posterior division gives the iliolumbar, lateral sacral and superior gluteal arteries; the anterior division gives obturator, internal pudendal and inferior gluteal among visceral branches.', 'Its branching pattern organizes all gluteal and obturator supply — orientation only.', { course: 'Common iliac bifurcation → posteromedial into the pelvis → anterior/posterior divisions at the greater sciatic foramen level.' }),
    e(GN, 'femoral-vessels', 'Femoral artery & vein', 'artery', 'Continuation of the external iliac vessels below the inguinal ligament; the artery is the palpable pulse of the groin.', 'Right and left artery and vein meshes shown in the femoral triangle: NAVL arrangement lateral to medial (nerve outside the sheath, artery, vein, lymphatics). The vein lies medial to the artery in the triangle and deep to it lower down.', 'The mid-inguinal point marks the artery surface position — landmark orientation only.', { course: 'Inguinal ligament → femoral triangle → adductor canal (distal course outside this module).' }),
    e(GN, 'deep-femoral', 'Deep femoral artery & vein (profunda femoris)', 'artery', 'Largest branch of the femoral artery, supplying the thigh compartments; arises posterolaterally in the triangle.', 'Right and left artery and vein meshes shown; gives the medial and lateral circumflex femoral arteries near its origin and the perforating arteries to the posterior compartment.', 'The profunda is the main collateral route around femoral artery occlusion — orientation only.', { course: 'Femoral triangle → posterior to the femoral vessels → between pectineus and adductor longus → perforating branches.' }),
    e(GN, 'sup-gluteal-v', 'Superior gluteal artery & veins', 'artery', 'Largest branch of the posterior division of the internal iliac artery; chief supply of the gluteal muscles.', 'Artery and veins shown bilaterally; exit the pelvis above the piriformis with the superior gluteal nerve and divide into superficial (gluteus maximus) and deep (medius/minimus, with anastomoses) branches.', 'Suprapiriform exit is the key relation — orientation only.', { course: 'Internal iliac posterior division → greater sciatic foramen above piriformis → gluteal region.' }),
    e(GN, 'inf-gluteal-v', 'Inferior gluteal artery & veins', 'artery', 'Branch of the anterior division of the internal iliac artery; supplies gluteus maximus and contributes to the trochanteric and cruciate anastomoses.', 'Artery and veins shown bilaterally; exit below the piriformis medial to the sciatic nerve with the inferior gluteal nerve and posterior femoral cutaneous nerve.', 'Infrapiriform exit with the sciatic nerve is the key relation — orientation only.', { course: 'Internal iliac anterior division → greater sciatic foramen below piriformis → gluteus maximus.' }),
    e(GN, 'circumflex-femoral', 'Medial & lateral circumflex femoral arteries', 'artery', 'The medial circumflex (usually from the deep femoral) is the chief supply of the femoral head via retinacular branches; the lateral circumflex supplies the anterior/lateral thigh and joins the trochanteric anastomosis.', 'Medial and lateral circumflex arteries and veins, plus the descending branch of the lateral circumflex, shown bilaterally; the medial circumflex passes between pectineus and iliopsoas, then between obturator externus and quadratus femoris to reach the back of the neck.', 'The medial circumflex retinacular course explains femoral-head perfusion risk in neck fractures — orientation only.', { course: 'Deep femoral (or femoral) → around the femoral neck → retinacular branches (medial) / transverse and descending branches (lateral).' }),
    e(GN, 'obturator-a', 'Obturator artery', 'artery', 'Branch of the anterior division of the internal iliac artery; accompanies the obturator nerve through the obturator canal to the medial thigh.', 'Right and left meshes shown; gives the foveal (acetabular) branch to the ligament of the head of the femur and anastomoses with the medial circumflex femoral. An accessory obturator artery from the inferior epigastric is a common variant.', 'The corona mortis variant anastomosis is a pelvic-surgery caution — orientation only.', { course: 'Internal iliac anterior division → lateral pelvic wall → obturator canal → medial thigh branches.' }),
    e(GN, 'internal-pudendal', 'Internal pudendal artery & vein', 'artery', 'Chief supply of the perineum; branch of the anterior division of the internal iliac artery.', 'Artery and vein shown bilaterally; exit the greater sciatic foramen, cross the ischial spine with the pudendal nerve, and re-enter via the lesser sciatic foramen to the pudendal canal.', 'Shares the pudendal nerve pathway around the ischial spine — orientation only.', { course: 'Internal iliac → greater sciatic foramen → ischial spine → lesser sciatic foramen → perineum.' }),
    e(GN, 'perforating-pudendal', 'Perforating & external pudendal vessels', 'artery', 'Perforating femoral arteries (usually three plus the terminal profunda) pierce the adductor magnus to supply the posterior thigh; external pudendal arteries (superficial and deep) supply the external genital region.', 'Perforating femoral arteries, superficial and deep external pudendal arteries and external pudendal veins shown bilaterally.', 'Perforators feed the cruciate anastomosis at the hip — collateral-route anatomy.', { course: 'Deep femoral → through adductor magnus → posterior compartment (perforators); femoral → medial to external genitalia (external pudendal).' }),
    mu(GN, 'levator-ani', 'Levator ani (pubococcygeus & iliococcygeus) & coccygeus', 'muscleDeep', 'Pubococcygeus: posterior pubis. Iliococcygeus: tendinous arch of the obturator fascia. Coccygeus: ischial spine.', 'Perineal body, anococcygeal ligament and coccyx (levator ani); sacrum and coccyx (coccygeus).', 'Pudendal nerve branches and direct S3–S4 branches (levator ani); S4–S5 (coccygeus).', 'Form the pelvic diaphragm supporting the pelvic viscera and maintaining continence; coccygeus completes the diaphragm posteriorly.', 'Pubococcygeus, iliococcygeus, coccygeus and the tendinous arch of levator ani are separate bilateral meshes; the arch is the fascial origin line on the obturator internus fascia.', 'Pelvic-floor support anatomy frames prolapse and continence discussions — orientation only.'),
    io(GN, 'pelvic-floor-fascia', 'Obturator & pelvic-floor fascia', 'fascia', 'The obturator fascia lines the lateral pelvic wall over obturator internus and thickens into the tendinous arch of levator ani and the pudendal canal; the superior fascia of the pelvic diaphragm covers levator ani.', 'Not separately segmented; the tendinous arch mesh marks the key thickening.', 'Fascial support layers are the anatomical basis of pelvic-floor repair concepts — orientation only.'),
    io(GN, 'sciatic-foramina', 'Greater & lesser sciatic foramina', 'space', 'Openings formed by the sciatic notches plus the sacrospinous and sacrotuberous ligaments; the gateways between pelvis, gluteal region and perineum.', 'Greater foramen contents (above down): superior gluteal vessels/nerve (above piriformis), then sciatic nerve, inferior gluteal and internal pudendal vessels, pudendal nerve, posterior femoral cutaneous nerve and the nerves to obturator internus/quadratus femoris (below piriformis). Lesser foramen transmits the obturator internus tendon, pudendal nerve and internal pudendal vessels. Spaces without their own meshes.', 'The suprapiriform/infrapiriform division organizes every gluteal neurovascular entry in this module.'),

    // ================= Clinical surface anatomy =================
    io(GC, 'gt-surface', 'Greater trochanter & lateral hip region', 'bone', 'The bony prominence palpable on the outer hip; overlying it are the trochanteric bursae and the gluteus medius/minimus insertions.', 'Lateral hip tenderness maps to the gluteal tendon and bursa complex at the trochanteric facets; the iliotibial tract glides over it in flexion/extension.', 'Lateral hip pain anatomy (tendons, bursae, IT tract) is an educational map — not a diagnosis.'),
    io(GC, 'asis-surface', 'ASIS & inguinal region landmarks', 'bone', 'ASIS (sartorius origin, lateral inguinal ligament anchor) to pubic tubercle (medial anchor) defines the groin crease line.', 'The lateral femoral cutaneous nerve passes near the ASIS; the femoral pulse lies below the mid-inguinal point; the femoral triangle opens below the ligament.', 'Groin surface anatomy orients the femoral vessels and nerve — landmark learning only.'),
    io(GC, 'pubic-surface', 'Pubic tubercle & symphysis region', 'bone', 'Midline anterior landmarks: symphysis (joint), pubic crest and tubercle (inguinal ligament, rectus abdominis, adductor longus origin).', 'Adductor longus tendon is palpable just lateral to the tubercle with resisted adduction.', 'Pubic-region pain has a broad muscular and joint differential — anatomy orientation only.'),
    io(GC, 'psis-surface', 'PSIS & posterior pelvic landmarks', 'bone', 'The PSIS dimples overlie the S2 level and the SI joint; the posterior crest carries the thoracolumbar fascia.', 'The Fortin finger region (pain within ~1 cm of the PSIS) is a described SI examination association; the sacral hiatus and cornu lie inferiorly in the midline.', 'SI-region localization is an examination concept, not a diagnosis — orientation only.'),
    io(GC, 'ischial-surface', 'Ischial tuberosity region', 'bone', 'Palpable in the lower buttock with the hip flexed (it emerges from under gluteus maximus); the sitting weight-bearing point.', 'Common hamstring origin and sacrotuberous ligament attach here; the sciatic bursa of gluteus maximus cushions it; the sciatic nerve passes just lateral.', 'Buttock pain in sitting maps to the tuberosity, its bursa and the hamstring origin — orientation only.'),
    io(GC, 'gluteal-quadrants', 'Gluteal region quadrants & injection-safety concept', 'space', 'The buttock divided by lines from the PSIS and the highest crest point: the sciatic nerve and gluteal vessels occupy the lower quadrants; the superolateral quadrant is relatively free of major neurovascular structures.', 'A surface-projection teaching rule for the deep anatomy mapped in this module (sciatic nerve, superior/inferior gluteal vessels).', 'Quadrant teaching is an anatomical safety concept — this atlas does not instruct procedures.'),
    io(GC, 'deep-gluteal-space', 'Deep gluteal space & posterior hip relation', 'space', 'The space deep to gluteus maximus containing the piriformis, the deep rotator stack, the sciatic nerve and the gluteal/pudendal neurovascular bundles.', 'Posterior hip and deep buttock symptoms map anatomically to the sciatic nerve, the piriformis relation and the ischiofemoral interval (quadratus femoris region).', 'Deep gluteal syndrome is a clinical-anatomical framework; this atlas teaches the anatomy, not the diagnosis.'),
    io(GC, 'anterior-hip-region', 'Anterior hip & femoral triangle relation', 'space', 'Groin-dominant symptoms map to the hip joint itself (capsule, labrum), the iliopsoas tendon/bursa and the femoral triangle contents.', 'The hip joint lies deep to the femoral vessels at the mid-inguinal region; iliopsoas snaps and strains occur at the iliopectineal region.', 'Groin pain has articular, muscular and hernia differentials — anatomy orientation only.'),
    io(GC, 'hip-pain-map', 'Hip-region pain — anatomy orientation', 'space', 'Educational map separating articular (groin, capsule/labrum), tendinous (lateral gluteal, proximal hamstring, adductor origin) and neural (sciatic, LFCN, obturator referral) anatomy.', 'Groin suggests joint/iliopsoas region; lateral suggests trochanteric complex; posterior suggests deep gluteal or SI region; medial suggests adductor/obturator territory.', 'These maps organize study; they cannot assign a cause without examination and imaging.'),
    io(GC, 'hip-red-flags', 'Hip & pelvic red-flag anatomy', 'nerve', 'Orientation for time-sensitive presentations at the hip and pelvis.', 'Pelvic-ring trauma with haemodynamic instability (rich pelvic venous plexus and iliac vessels), femoral-head perfusion risk after displaced neck fracture (medial circumflex anatomy), septic-arthritis anatomy of the joint space, and new neurological deficit in sciatic/femoral/obturator territories.', 'Major trauma, a hot swollen joint with systemic illness, or new loss of leg nerve function warrants urgent clinical assessment — this atlas cannot triage, diagnose or plan treatment.'),
  ],
  views: [
    { id: 'exam', name: 'Hip & pelvis examination', caption: 'Regional examination associations.', orientation: ['Right', 'Left'], shapes: [], exam: {
      palpation: ['Iliac crest from ASIS to PSIS; ASIS (sartorius), pubic tubercle and symphysis anteriorly.', 'Greater trochanter laterally; ischial tuberosity with the hip flexed; PSIS dimples and sacral midline posteriorly.', 'Adductor longus tendon in the groin with resisted adduction; femoral pulse below the mid-inguinal point.'],
      movement: ['Hip flexion, extension, abduction, adduction, internal and external rotation; log-roll concept for resting rotation.', 'Single-leg-stance pelvic control (Trendelenburg concept) for the abductor group.', 'Resisted hip flexion (iliopsoas), adduction (adductors) and extension (gluteus maximus/hamstrings) as muscle-group screening.'],
      danger: ['Sciatic nerve in the deep gluteal space (infrapiriform, between trochanter and tuberosity); femoral nerve/artery/vein in the triangle (NAVL).', 'Medial circumflex femoral retinacular branches on the posterior femoral neck; superior gluteal neurovascular bundle between medius and minimus.', 'Red flags: pelvic trauma with instability, hot joint with systemic illness, new sciatic/femoral/obturator deficit — urgent clinical assessment.'],
      tests: ['FABER/Patrick-type and FADIR-type positions as joint-region associations — not diagnoses.', 'Resisted abduction and single-leg stance for the superior gluteal nerve/muscle group.', 'Dermatomal vs peripheral-nerve sensory screening concepts (LFCN lateral thigh, obturator medial thigh, sciatic below-knee territories).'] } },
    { id: 'patterns', name: 'Clinical patterns', caption: 'Educational comparison of common anatomical patterns.', orientation: ['Right', 'Left'], shapes: [], exam: {
      palpation: ['Groin (joint/iliopsoas) vs lateral (trochanteric complex) vs posterior (deep gluteal/SI) vs medial (adductor/obturator) region mapping.'],
      movement: ['Intra-articular patterns limit rotation early; extra-articular muscular patterns hurt with resisted action of one group.'],
      danger: ['Displaced femoral neck fracture threatens retinacular head supply; posterior dislocation endangers the sciatic nerve.'],
      tests: ['Hip-joint pain commonly refers to the groin and may reach the knee via obturator articular branches — an anatomical referral concept.', 'No single test isolates one structure; patterns are study frameworks only.'] } },
  ],
};

const RULES: [RegExp, string][] = [
  // bones
  [/^hip bone$/, 'hip-bone'], [/^femur$/, 'femur-proximal'], [/^sacrum$/, 'sacrum'],
  [/^coccyx$/, 'coccyx'], [/^sacrococcygeal symphysis$/, 'coccyx'],
  // pelvic joints & ligaments
  [/^(anterior|posterior|interosseous) sacro-iliac ligament$/, 'si-joint'],
  [/^(pubic symphysis|interpubic disc|(superior|inferior) pubic ligament)$/, 'pubic-symphysis'],
  [/^(sacrospinous|sacrotuberous) ligament$/, 'sacro-ligs'],
  [/^iliolumbar ligament$/, 'iliolumbar'], [/^obturator membrane$/, 'obturator-membrane'],
  [/^inguinal ligament$/, 'inguinal-lig'],
  // hip joint
  [/^articular capsule of hip joint$/, 'hip-capsule'], [/^acetabular labrum$/, 'labrum'],
  [/^transverse acetabular ligament$/, 'transverse-acetabular'],
  [/^ligament of head of femur$/, 'lig-head-femur'],
  [/^(descending|transverse) part of iliofemoral ligament$/, 'iliofemoral'],
  [/^pubofemoral ligament$/, 'pubofemoral'], [/^ischiofemoral ligament$/, 'ischiofemoral'],
  // gluteal & deep rotators
  [/^gluteus maximus muscle$/, 'gluteus-maximus'], [/^gluteus medius muscle$/, 'gluteus-medius'], [/^gluteus minimus muscle$/, 'gluteus-minimus'],
  [/^tensor fasciae latae$/, 'tfl'], [/^iliotibial tract$/, 'it-tract'],
  [/^(piriformis muscle|piriformis fascia|bursa of piriformis muscle)$/, 'piriformis'],
  [/^obturator internus$/, 'obturator-internus'], [/^obturator externus$/, 'obturator-externus'],
  [/^(superior|inferior) gemellus muscle$/, 'gemelli'], [/^quadratus femoris muscle$/, 'quadratus-femoris'],
  [/^(trochanteric bursa of gluteus (maximus|medius|minimus) muscle|subcutaneous trochanteric bursa|intermuscular gluteal bursae)$/, 'trochanteric-bursae'],
  [/^sciatic bursa of (gluteus maximus muscle|obturator internus)$/, 'sciatic-bursae'],
  // anterior hip & iliopsoas
  [/^psoas major$/, 'psoas'], [/^iliacus muscle$/, 'iliacus'],
  [/^(iliopsoas fascia|subtendinous bursa of iliacus muscle)$/, 'iliopsoas-fascia'],
  [/^rectus femoris muscle$/, 'rectus-femoris'], [/^sartorius muscle$/, 'sartorius'], [/^pectineus muscle$/, 'pectineus'],
  // medial thigh
  [/^adductor longus$/, 'adductor-longus'], [/^adductor brevis$/, 'adductor-brevis'], [/^adductor magnus$/, 'adductor-magnus'],
  [/^\(adductor minimus\)$/, 'adductor-minimus'], [/^gracilis muscle$/, 'gracilis'],
  [/^(semitendinosus|semimembranosus) muscle$|^long head of biceps femoris$/, 'hamstring-origins'],
  [/^vastus (lateralis|medialis|intermedius) muscle$/, 'vastus-origins'],
  // pelvic floor
  [/^(pubococcygeus|iliococcygeus|coccygeus) muscle$|^tendinous arch of levator ani$/, 'levator-ani'],
  // nerves
  [/^sciatic nerve$/, 'sciatic'], [/^superior gluteal nerve$/, 'sup-gluteal-n'],
  [/^nerve to (piriformis|quadratus femoris) muscle$/, 'deep-rotator-nerves'],
  [/^pudendal nerve$/, 'pudendal'],
  [/^(posterior femoral cutaneous nerve|(anterior|posterior) root of posterior femoral cutaneous nerve)$/, 'pfcn'],
  [/^lateral femoral cutaneous nerve$/, 'lfcn'],
  [/^(femoral nerve|anterior cutaneous branches of femoral nerve)$/, 'femoral-n'],
  [/^(obturator nerve|(anterior|posterior) branch of obturator nerve)$/, 'obturator-n'],
  [/^(genitofemoral nerve|(femoral|genital) branch of genitofemoral nerve|ilio-inguinal nerve)$/, 'genitofemoral'],
  // vessels
  [/^common iliac (artery|vein)$/, 'common-iliac'], [/^external iliac (artery|vein)$/, 'external-iliac'],
  [/^(internal iliac (artery|vein)|(anterior|posterior) division of internal iliac artery)$/, 'internal-iliac'],
  [/^femoral (artery|vein)$/, 'femoral-vessels'], [/^deep femoral (artery|vein)$/, 'deep-femoral'],
  [/^superior gluteal (artery|veins)$/, 'sup-gluteal-v'], [/^inferior gluteal (artery|veins)$/, 'inf-gluteal-v'],
  [/^(medial|lateral) circumflex femoral (artery|veins)$|^descending branch of lateral circumflex femoral artery$/, 'circumflex-femoral'],
  [/^obturator artery$/, 'obturator-a'], [/^internal pudendal (artery|vein)$/, 'internal-pudendal'],
  [/^(perforating femoral arteries|(superficial|deep) external pudendal artery|external pudendal veins)$/, 'perforating-pudendal'],
];
export function matchHipPelvisMesh(name: string) {
  const n = name.replace(/\.(r|l)$/i, '').toLowerCase();
  for (const [re, id] of RULES) if (re.test(n)) return { regionId: 'hip-pelvis', id };
  return null;
}
/** Bilateral pelvis/hip membership; spatial clipping then crops to the chosen side. */
export function isHipPelvisMesh(name: string) { return matchHipPelvisMesh(name) !== null; }
